var e=[{id:`barbell-bench-press`,group:`chest`,name:{en:`Barbell Bench Press`,ar:`ضغط البنش بالبار`},equipment:{en:`Barbell + bench`,ar:`بار + بنش`},level:`intermediate`,steps:{en:[`Lie on the bench with eyes under the bar, feet planted, and shoulder blades pulled back and down.`,`Grip slightly wider than shoulder width, unrack the bar, and lower it slowly to mid-chest.`,`Press the bar up until arms are straight, keeping elbows at about 45 degrees from your body.`],ar:[`استلقِ على البنش بعينيك تحت البار، وثبّت قدميك على الأرض واسحب لوحي الكتف للخلف والأسفل.`,`امسك البار بعرض أكبر قليلًا من الكتفين، واخرج البار، وأنزله ببطء إلى منتصف الصدر.`,`ادفع البار لأعلى حتى يستهوي ذراعاك، مع إبقاء المرفقين بزاوية 45 درجة تقريبًا عن الجسم.`]}},{id:`incline-barbell-press`,group:`chest`,name:{en:`Incline Barbell Press`,ar:`ضغط البنش المائل بالبار`},equipment:{en:`Barbell + incline bench`,ar:`بار + بنش مائل`},level:`intermediate`,steps:{en:[`Set the bench to a 30-45 degree incline and sit back with shoulder blades squeezed together.`,`Lower the bar to the upper chest, then press up and slightly back over the shoulders.`],ar:[`اضبط البنش على ميل 30-45 درجة واجلس مستندًا مع قبض لوحي الكتف معًا.`,`أنزل البار إلى أعلى الصدر، ثم ادفع لأعلى وللخلف قليلًا فوق الكتفين.`]}},{id:`dumbbell-bench-press`,group:`chest`,name:{en:`Dumbbell Bench Press`,ar:`ضغط البنش بالدمبل`},equipment:{en:`Dumbbells + bench`,ar:`دمبل + بنش`},level:`beginner`,steps:{en:[`Sit on the bench with dumbbells resting on your thighs, then kick them up as you lie back.`,`Press the dumbbells up until arms are extended, then lower until your elbows reach chest level.`],ar:[`اجلس على البنش والدمبل مستقر على فخذيك، ثم ارفعهما وأنت تستلقي.`,`ادفع الدمبل لأعلى حتى يستهوي الذراعان، ثم أنزلهما حتى يصل المرفقان إلى مستوى الصدر.`]}},{id:`incline-dumbbell-press`,group:`chest`,name:{en:`Incline Dumbbell Press`,ar:`ضغط مائل بالدمبل`},equipment:{en:`Dumbbells + incline bench`,ar:`دمبل + بنش مائل`},level:`beginner`,steps:{en:[`Lie back on a 30-45 degree bench with a dumbbell in each hand at shoulder level.`,`Press up and slightly inward until the dumbbells nearly touch, then lower with control.`],ar:[`استلقِ على بنش مائل 30-45 درجة ودمبل في كل يد عند مستوى الكتف.`,`ادفع لأعلى وللداخل قليلًا حتى يقترب الدمبل من الآخر، ثم أنزل بتحكم.`]}},{id:`dumbbell-fly`,group:`chest`,name:{en:`Dumbbell Fly`,ar:`تفتيح بالدمبل`},equipment:{en:`Dumbbells + bench`,ar:`دمبل + بنش`},level:`beginner`,steps:{en:[`Lie on a flat bench holding dumbbells above your chest with a slight bend in the elbows.`,`Open your arms out to the sides until you feel a stretch in the chest, then hug the weights back up.`],ar:[`استلقِ على بنش مستوٍ ودمبل فوق الصدر مع انحناء بسيط في المرفقين.`,`افتح ذراعيك إلى الجانبين حتى تشعر بشد في الصدر، ثم اجمع الأوزان للداخل كالعناق.`]}},{id:`cable-crossover`,group:`chest`,name:{en:`Cable Crossover`,ar:`الكروس أوفر بالكابل`},equipment:{en:`Cable station`,ar:`جهاز كابل`},level:`beginner`,steps:{en:[`Stand between two high pulleys and grab a handle in each hand with a slight forward lean.`,`Bring your hands together in front of your chest in a hugging arc, squeeze, then return slowly.`],ar:[`قف بين بكرتين عاليتين وامسك مقبضًا في كل يد مع ميل بسيط للأمام.`,`اجمع يديك أمام صدرك بقوس كالعناق، اضغط العضلة، ثم ارجع ببطء.`]}},{id:`machine-chest-press`,group:`chest`,name:{en:`Machine Chest Press`,ar:`ضغط الصدر بالجهاز`},equipment:{en:`Chest press machine`,ar:`جهاز ضغط الصدر`},level:`beginner`,steps:{en:[`Adjust the seat so the handles line up with mid-chest and your back stays flat on the pad.`,`Press the handles forward until arms are extended without locking the elbows, then return slowly.`],ar:[`اضبط المقعد ليكون المقابض بمستوى منتصف الصدر ويبقى ظهرك ملتصقًا بالممسدة.`,`ادفع المقابض للأمام حتى يستهوي الذراعان دون قفل المرفقين، ثم ارجع ببطء.`]}},{id:`pec-deck`,group:`chest`,name:{en:`Pec Deck Fly`,ar:`بيك ديك (تفتيح بالجهاز)`},equipment:{en:`Pec deck machine`,ar:`جهاز بيك ديك`},level:`beginner`,steps:{en:[`Sit with your back flat and elbows at chest height against the pads or handles.`,`Squeeze your arms together in front of you, pause for a second, then open back with control.`],ar:[`اجلس بظهر مستوٍ والمرفقان بارتفاع الصدر على الممسدات أو المقابض.`,`اجمع ذراعيك أمامك واضغط، وتوقف ثانية، ثم افتح للخلف بتحكم.`]}},{id:`push-up`,group:`chest`,name:{en:`Push-Up`,ar:`الضغط`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Set hands slightly wider than the shoulders and form a straight line from head to heels.`,`Bend the elbows to lower your chest to just above the floor, then push back up as one solid piece.`],ar:[`ضع يديك بعرض أوسع قليلًا من الكتفين وكون خطًا مستقيمًا من الرأس إلى الكعبين.`,`اثنِ المرفقين لأنزل صدرك فوق الأرض بقليل، ثم ادفع لأعلى وانت ككتلة واحدة متصلة.`]}},{id:`decline-push-up`,group:`chest`,name:{en:`Decline Push-Up`,ar:`الضغط بميل هابط`},equipment:{en:`Bodyweight + bench`,ar:`وزن الجسم + بنش`},level:`intermediate`,steps:{en:[`Place your feet on a bench or box and hands on the floor in a strong plank.`,`Lower your chest toward the floor while keeping the hips level, then press back up.`],ar:[`ضع قدميك على بنش أو صندوق ويديك على الأرض في وضع بلانك ثابت.`,`أنزل صدرك نحو الأرض مع إبقاء الحوض مستويًا، ثم ادفع لأعلى.`]}},{id:`chest-dip`,group:`chest`,name:{en:`Chest Dip`,ar:`غطس الصدر (ديب)`},equipment:{en:`Dip bars`,ar:`متوازيان`},level:`intermediate`,steps:{en:[`Support yourself on the bars and lean your torso forward about 30 degrees.`,`Bend the elbows to lower until the shoulders reach elbow height, then press back up.`],ar:[`اتسك على المتوازيين ومِل جسمك للأمام بزاوية 30 درجة تقريبًا.`,`اثنِ المرفقين لأنزل حتى يصل الكتفان إلى مستوى المرفقين، ثم ادفع لأعلى.`]}},{id:`low-to-high-cable-fly`,group:`chest`,name:{en:`Low-to-High Cable Fly`,ar:`تفتيح الكابل من أسفل إلى أعلى`},equipment:{en:`Cable station`,ar:`جهاز كابل`},level:`beginner`,steps:{en:[`Set the pulleys low and hold a handle in each hand with a soft bend in the elbows.`,`Sweep your hands up and together toward shoulder height, squeeze the chest, then lower slowly.`],ar:[`اضبط البكرتين في الأسفل وامسك مقبضًا في كل يد مع انحناء بسيط في المرفقين.`,`ارفع يديك قوسًا حتى تلتقيا بارتفاع الكتف، اضغط الصدر، ثم أنزل ببطء.`]}}],t=[{id:`deadlift`,group:`back`,name:{en:`Deadlift`,ar:`الرفعة الميتة`},equipment:{en:`Barbell`,ar:`بار`},level:`advanced`,steps:{en:[`Stand over the bar with feet hip-width, hinge down, and grip just outside the legs with a flat back.`,`Brace your core, drive through the floor, and stand tall with hips and shoulders rising together.`,`Lower the bar by pushing the hips back and keeping it close to your legs the whole way.`],ar:[`قف فوق البار بعرض الحوض، انحنِ من الورك، وامسك خارج الساقين بظهر مستوٍ.`,`ثبّت بطنك، ادفع الأرض بأقدامك، وانهض منتصبًا مع ارتفاع الحوض والكتفين معًا.`,`أنزل البار بدفع الحوض للخلف مع إبقائه قريبًا من ساقيك في المسار كله.`]}},{id:`barbell-row`,group:`back`,name:{en:`Bent-Over Barbell Row`,ar:`السحب بالبار منحنيًا`},equipment:{en:`Barbell`,ar:`بار`},level:`intermediate`,steps:{en:[`Hinge at the hips to about 45 degrees with a flat back and the bar hanging under your shoulders.`,`Row the bar into your lower ribs by driving the elbows back, then lower it under control.`],ar:[`انحنِ من الورك بزاوية 45 درجة بظهر مستوٍ والبار متدلٍ تحت الكتفين.`,`اسحب البار إلى أسفل القفص الصدري بدفع المرفقين للخلف، ثم أنزله بتحكم.`]}},{id:`lat-pulldown`,group:`back`,name:{en:`Lat Pulldown`,ar:`السحب الأمامي (لات بول داون)`},equipment:{en:`Lat pulldown machine`,ar:`جهاز السحب الأمامي`},level:`beginner`,steps:{en:[`Grip the bar wide, sit with thighs locked under the pads, and lean back slightly.`,`Pull the bar to your upper chest by driving the elbows down, then let it rise slowly.`],ar:[`امسك البار بعرض كبير، اجلس والفخذان مثبتان تحت الممسدات، ومِل للخلف قليلًا.`,`اسحب البار إلى أعلى صدرك بدفع المرفقين للأسفل، ثم اتركه يصعد ببطء.`]}},{id:`pull-up`,group:`back`,name:{en:`Pull-Up`,ar:`العقلة`},equipment:{en:`Pull-up bar`,ar:`بار العقلة`},level:`intermediate`,steps:{en:[`Hang from the bar with an overhand grip slightly wider than the shoulders.`,`Pull yourself up until your chin clears the bar, then lower with control to a full hang.`],ar:[`تدلَّ من البار بقبضة عليا أوسع قليلًا من الكتفين.`,`اسحب جسمك لأعلى حتى يتجاوز ذقنك البار، ثم انزل بتحكم حتى التدلي الكامل.`]}},{id:`chin-up`,group:`back`,name:{en:`Chin-Up`,ar:`العقلة المقلوبة (تشين أب)`},equipment:{en:`Pull-up bar`,ar:`بار العقلة`},level:`beginner`,steps:{en:[`Hang with an underhand grip at shoulder width and shoulders engaged.`,`Pull up until the chin is over the bar while driving the elbows toward your ribs.`],ar:[`تدلَّ بقبضة سفلية بعرض الكتفين مع شد الكتفين.`,`اسحب جسمك حتى يتجاوز ذقنك البار مع دفع المرفقين نحو ضلوعك.`]}},{id:`seated-cable-row`,group:`back`,name:{en:`Seated Cable Row`,ar:`السحب القفسي جالسًا`},equipment:{en:`Cable row machine`,ar:`جهاز السحب القفسي`},level:`beginner`,steps:{en:[`Sit tall with knees slightly bent and grab the handle with arms extended.`,`Pull the handle to your stomach while squeezing the shoulder blades, then extend forward slowly.`],ar:[`اجلس منتصبًا والركبتان مثنيتان قليلًا وامسك المقبض بذراعين ممدودتين.`,`اسحب المقبض إلى بطنك مع قبض لوحي الكتف، ثم امتد للأمام ببطء.`]}},{id:`one-arm-dumbbell-row`,group:`back`,name:{en:`One-Arm Dumbbell Row`,ar:`السحب بالدمبل بذراع واحدة`},equipment:{en:`Dumbbell + bench`,ar:`دمبل + بنش`},level:`beginner`,steps:{en:[`Place one knee and hand on a bench, keep the back flat, and let the dumbbell hang straight down.`,`Row the weight to your hip, keeping the elbow close to the body, then lower it fully.`],ar:[`ضع ركبة ويد على البنش مع ظهر مستوٍ واترك الدمبل يتدلى للأسفل.`,`اسحب الوزن نحو الورك مع إبقاء المرفق قريبًا من الجسم، ثم أنزله بالكامل.`]}},{id:`t-bar-row`,group:`back`,name:{en:`T-Bar Row`,ar:`سحب تي-بار`},equipment:{en:`T-bar row machine or landmine`,ar:`جهاز تي-بار أو لاندمين`},level:`intermediate`,steps:{en:[`Straddle the bar, hinge to about 45 degrees, and grip the handles with a neutral spine.`,`Pull the weight toward your chest, squeeze the back, then lower slowly without rounding.`],ar:[`قف معتنقًا البار من فوق، انحنِ بزاوية 45 درجة، وامسك المقابض بظهر محايد.`,`اسحب الوزن نحو صدرك واضغط الظهر، ثم أنزل ببطء دون تقويس.`]}},{id:`chest-supported-row`,group:`back`,name:{en:`Chest-Supported Row`,ar:`السحب بمسندي الصدر`},equipment:{en:`Incline bench or row machine`,ar:`بنش مائل أو جهاز سحب`},level:`beginner`,steps:{en:[`Lie chest-down on an incline bench with dumbbells hanging below your shoulders.`,`Row both weights up until the elbows pass your torso, then lower with control.`],ar:[`استلقِ بصدرك على بنش مائل والدمبل متدلٍ تحت الكتفين.`,`اسحب الوزنين لأعلى حتى يتجاوز المرفقان جذعك، ثم أنزل بتحكم.`]}},{id:`straight-arm-pulldown`,group:`back`,name:{en:`Straight-Arm Pulldown`,ar:`السحب بذراعين ممدودتين`},equipment:{en:`Cable station`,ar:`جهاز كابل`},level:`beginner`,steps:{en:[`Stand facing a high pulley and hold the bar with arms straight and a slight forward lean.`,`Sweep the bar down to your thighs using the lats, pause, then return with control.`],ar:[`قف مواجهًا بكرًا عاليًا وامسك البار بذراعين ممدودتين وميل بسيط للأمام.`,`اسحب البار نحو فخذيك بالظهر (اللاتس)، توقف، ثم ارجع بتحكم.`]}},{id:`face-pull`,group:`back`,name:{en:`Face Pull`,ar:`سحب الوجه`},equipment:{en:`Cable with rope`,ar:`كابل بحبل`},level:`beginner`,steps:{en:[`Set a rope at upper-chest height and step back to create tension with arms extended.`,`Pull the rope toward your forehead, splitting the hands beside your ears, then return slowly.`],ar:[`اضبط الحبل بارتفاع أعلى الصدر وتراجع خطوة لخلق شد مع ذراعين ممدودتين.`,`اسحب الحبل نحو جبهتك مع فصل اليدين بجانب الأذنين، ثم ارجع ببطء.`]}},{id:`rack-pull`,group:`back`,name:{en:`Rack Pull`,ar:`الرفعة من الحامل`},equipment:{en:`Barbell + rack`,ar:`بار + رف`},level:`intermediate`,steps:{en:[`Set the bar on the rack at knee height and hinge to grip it with a flat back.`,`Drive the hips forward to stand tall, squeezing the glutes at the top, then reverse.`],ar:[`اضبط البار على الرف بارتفاع الركبة وانحنِ لتمسكه بظهر مستوٍ.`,`ادفع الحوض للأمام لتنهض منتصبًا مع ضغط المؤخرة في الأعلى، ثم ارجع بالعكس.`]}},{id:`inverted-row`,group:`back`,name:{en:`Inverted Row`,ar:`السحب المعكوس`},equipment:{en:`Bar or rings`,ar:`بار أو حلقات`},level:`beginner`,steps:{en:[`Set a bar at waist height and hang beneath it holding it with straight arms.`,`Pull your chest to the bar while keeping the body rigid, then lower slowly.`],ar:[`اضبط بارًا بارتفاع الخصر وتدلَّ تحته ماسكًا بذراعين ممدودتين.`,`اسحب صدرك إلى البار مع إبقاء الجسم متصلبًا، ثم أنزل ببطء.`]}},{id:`barbell-shrug`,group:`back`,name:{en:`Barbell Shrug`,ar:`رفع الكتفين بالبار (شراغ)`},equipment:{en:`Barbell`,ar:`بار`},level:`beginner`,steps:{en:[`Hold the bar in front of your thighs with straight arms and an overhand grip.`,`Shrug your shoulders straight up toward your ears, pause at the top, then lower fully.`],ar:[`امسك البار أمام فخذيك بذراعين ممدودتين وقبضة عليا.`,`ارفع كتفيك مستقيمًا نحو أذنيك، توقف في الأعلى، ثم أنزل بالكامل.`]}},{id:`good-morning`,group:`back`,name:{en:`Good Morning`,ar:`قوس الخصر (جود مورنينج)`},equipment:{en:`Barbell`,ar:`بار`},level:`advanced`,steps:{en:[`Rest the bar across your upper back and stand tall with a braced core.`,`Push the hips back and hinge forward until the torso nears parallel, then stand back up.`],ar:[`ضع البار على أعلى ظهرك وانهض منتصبًا مع بطن مشدود.`,`ادفع الحوض للخلف وانحنِ حتى يقترب الجذع من الأفقي، ثم ارجع للوقوف.`]}}],n=[{id:`overhead-press`,group:`shoulders`,name:{en:`Overhead Press`,ar:`الضغط فوق الرأس بالبار`},equipment:{en:`Barbell`,ar:`بار`},level:`intermediate`,steps:{en:[`Hold the bar at collarbone height with elbows stacked under the bar and a braced core.`,`Press the bar straight up, moving the head back slightly as it passes the face, then lock out overhead.`],ar:[`امسك البار بارتفاع الترقوة والمرفقان تحت البار والبطن مشدود.`,`ادفع البار مستقيمًا لأعلى، وأرجع رأسك قليلًا عند مروره بالوجه، ثم ثبت فوق الرأس.`]}},{id:`seated-dumbbell-press`,group:`shoulders`,name:{en:`Seated Dumbbell Press`,ar:`الضغط جالسًا بالدمبل`},equipment:{en:`Dumbbells + bench`,ar:`دمبل + بنش`},level:`beginner`,steps:{en:[`Sit on a bench with back support, dumbbells at shoulder level and palms facing forward.`,`Press both dumbbells up until arms are extended, then lower back to the starting position.`],ar:[`اجلس على بنش بظهر مسنود والدمبل عند مستوى الكتف والكفان للأمام.`,`ادفع الدمبل لأعلى حتى يستهوي الذراعان، ثم أنزلهما لنقطة البداية.`]}},{id:`arnold-press`,group:`shoulders`,name:{en:`Arnold Press`,ar:`ضغط أرنولد`},equipment:{en:`Dumbbells`,ar:`دمبل`},level:`intermediate`,steps:{en:[`Start with dumbbells at shoulder height and palms facing your body.`,`Press up while rotating the palms to face forward at the top, then reverse the motion on the way down.`],ar:[`ابدأ بالدمبل عند مستوى الكتف والكفان نحو جسمك.`,`ادفع لأعلى مع تدوير الكفين للأمام في القمة، ثم اعكس الحركة عند النزول.`]}},{id:`lateral-raise`,group:`shoulders`,name:{en:`Lateral Raise`,ar:`الرفرفة الجانبية`},equipment:{en:`Dumbbells`,ar:`دمبل`},level:`beginner`,steps:{en:[`Stand with dumbbells at your sides and a slight bend in the elbows.`,`Raise the arms out to shoulder height, leading with the elbows, then lower slowly.`],ar:[`قف والدمبل على جانبيك مع انحناء بسيط في المرفقين.`,`ارفع الذراعين جانبيًا حتى مستوى الكتف بالقيادة من المرفقين، ثم أنزل ببطء.`]}},{id:`front-raise`,group:`shoulders`,name:{en:`Front Raise`,ar:`الرفرفة الأمامية`},equipment:{en:`Dumbbells or plate`,ar:`دمبل أو قرص`},level:`beginner`,steps:{en:[`Hold the weight in front of your thighs with arms straight and shoulders back.`,`Raise it forward to eye level without swinging, then lower under control.`],ar:[`امسك الوزن أمام فخذيك بذراعين ممدودتين وكتفين للخلف.`,`ارفعه للأمام حتى مستوى العين دون تأرجح، ثم أنزله بتحكم.`]}},{id:`rear-delt-fly`,group:`shoulders`,name:{en:`Rear Delt Fly`,ar:`الرفرفة الخلفية`},equipment:{en:`Dumbbells + bench`,ar:`دمبل + بنش`},level:`beginner`,steps:{en:[`Hinge forward at the hips with a flat back and let the dumbbells hang below you.`,`Raise the arms out to the sides until level with the shoulders, then lower slowly.`],ar:[`انحنِ من الورك بظهر مستوٍ واترك الدمبل يتدلى تحتك.`,`ارفع الذراعين جانبيًا حتى مستوى الكتفين، ثم أنزلهما ببطء.`]}},{id:`reverse-pec-deck`,group:`shoulders`,name:{en:`Reverse Pec Deck`,ar:`بيك ديك العكسي`},equipment:{en:`Pec deck machine`,ar:`جهاز بيك ديك`},level:`beginner`,steps:{en:[`Sit facing the machine with chest on the pad and hands on the handles.`,`Open your arms back in a wide arc until level with the shoulders, then return slowly.`],ar:[`اجلس مواجهًا للجهاز وصدرك على الممسدة ويديك على المقابض.`,`افتح ذراعيك للخلف بقوس واسع حتى مستوى الكتفين، ثم ارجع ببطء.`]}},{id:`upright-row`,group:`shoulders`,name:{en:`Upright Row`,ar:`السحب الرأسي`},equipment:{en:`Barbell or dumbbells`,ar:`بار أو دمبل`},level:`intermediate`,steps:{en:[`Hold the bar at hip height with hands about shoulder-width apart.`,`Pull the elbows up and out until the bar reaches upper-abdominal height, then lower it slowly.`],ar:[`امسك البار بارتفاع الورك واليدان بعرض الكتفين تقريبًا.`,`ارفع المرفقين لأعلى وللخارج حتى يصل البار لأعلى البطن، ثم أنزله ببطء.`]}},{id:`cable-lateral-raise`,group:`shoulders`,name:{en:`Cable Lateral Raise`,ar:`الرفرفة الجانبية بالكابل`},equipment:{en:`Cable station`,ar:`جهاز كابل`},level:`beginner`,steps:{en:[`Stand sideways to a low pulley and hold the handle with the far hand across your body.`,`Raise the arm out to the side to shoulder height, pause, then resist on the way down.`],ar:[`قف جانبيًا أمام بكر منخفض وامسك المقبض باليد البعيدة عبر جسمك.`,`ارفع الذراع جانبًا حتى مستوى الكتف، توقف، ثم قاوم عند النزول.`]}},{id:`pike-push-up`,group:`shoulders`,name:{en:`Pike Push-Up`,ar:`ضغط البيك للكتفين`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`intermediate`,steps:{en:[`From a push-up position, walk the feet in and lift the hips high into an inverted V.`,`Bend the elbows to lower the top of your head toward the floor, then press back up.`],ar:[`من وضع الضغط، قرّب قدميك وارفع حوضك عاليًا لتشكيل حرف V مقلوب.`,`اثنِ المرفقين لأنزل أعلى رأسك نحو الأرض، ثم ادفع لأعلى.`]}}],r=[{id:`barbell-curl`,group:`arms`,name:{en:`Barbell Curl`,ar:`مرجفة الذراع بالبار`},equipment:{en:`Barbell`,ar:`بار`},level:`beginner`,steps:{en:[`Stand tall holding the bar with an underhand grip at shoulder width, elbows at your sides.`,`Curl the bar up by bending the elbows only, squeeze at the top, then lower slowly.`],ar:[`قف منتصبًا ماسكًا البار بقبضة سفلية بعرض الكتفين والمرفقان بجانب الجسم.`,`ارفع البار بحركة المرفقين فقط، اضغط في القمة، ثم أنزل ببطء.`]}},{id:`dumbbell-curl`,group:`arms`,name:{en:`Dumbbell Curl`,ar:`مرجفة الذراع بالدمبل`},equipment:{en:`Dumbbells`,ar:`دمبل`},level:`beginner`,steps:{en:[`Hold a dumbbell in each hand with palms forward and elbows pinned to your sides.`,`Curl one or both arms up, rotating the palm up as you rise, then lower under control.`],ar:[`امسك دمبلًا في كل يد والكفان للأمام والمرفقان مثبتان بجانب الجسم.`,`ارفع الذراع أو الذراعين مع تدوير الكف لأعلى أثناء الصعود، ثم أنزل بتحكم.`]}},{id:`hammer-curl`,group:`arms`,name:{en:`Hammer Curl`,ar:`مرجفة المطرقة`},equipment:{en:`Dumbbells`,ar:`دمبل`},level:`beginner`,steps:{en:[`Hold dumbbells at your sides with a neutral grip, palms facing each other.`,`Curl the weights up keeping the palms facing in, then lower them slowly.`],ar:[`امسك الدمبل على جانبيك بقبضة محايدة والكفان مواجهان لبعضهما.`,`ارفع الوزنين مع إبقاء الكفين للداخل، ثم أنزلهما ببطء.`]}},{id:`incline-dumbbell-curl`,group:`arms`,name:{en:`Incline Dumbbell Curl`,ar:`مرجفة على بنش مائل`},equipment:{en:`Dumbbells + incline bench`,ar:`دمبل + بنش مائل`},level:`intermediate`,steps:{en:[`Lie back on an incline bench and let the dumbbells hang straight down behind you.`,`Curl both arms up while keeping the elbows back, then lower to a full stretch.`],ar:[`استلقِ على بنش مائل واترك الدمبل يتدلى مستقيمًا خلفك.`,`ارفع الذراعين مع إبقاء المرفقين للخلف، ثم أنزل للشد الكامل.`]}},{id:`preacher-curl`,group:`arms`,name:{en:`Preacher Curl`,ar:`مرجفة البريشر`},equipment:{en:`Preacher bench + dumbbell or bar`,ar:`بنش بريشر + دمبل أو بار`},level:`beginner`,steps:{en:[`Place the backs of your upper arms flat against the preacher pad.`,`Curl the weight up until the arms are nearly straight overhead, then lower with control.`],ar:[`ضع الجزء الخلفي من ذراعيك مستويًا على مسند البريشر.`,`ارفع الوزن حتى تقترب الذراع من الاستقامة، ثم أنزل بتحكم.`]}},{id:`cable-curl`,group:`arms`,name:{en:`Cable Curl`,ar:`مرجفة الكابل`},equipment:{en:`Cable station`,ar:`جهاز كابل`},level:`beginner`,steps:{en:[`Attach a bar to the low pulley and hold it with an underhand grip, arms extended.`,`Curl toward your shoulders while keeping the elbows fixed, then return slowly against the resistance.`],ar:[`ثبّت بارًا على بكر منخفض وامسكه بقبضة سفلية وذراعين ممدودتين.`,`ارفع نحو كتفيك مع تثبيت المرفقين، ثم ارجع ببطء مقاومًا الشد.`]}},{id:`close-grip-bench-press`,group:`arms`,name:{en:`Close-Grip Bench Press`,ar:`ضغط البنش بالقبضة الضيقة`},equipment:{en:`Barbell + bench`,ar:`بار + بنش`},level:`intermediate`,steps:{en:[`Grip the bar just inside shoulder width and unrack it over your chest.`,`Lower the bar to your lower chest with elbows tucked, then press back up to lockout.`],ar:[`امسك البار بعرض أضيق قليلًا من الكتفين وأخرجه فوق صدرك.`,`أنزل البار إلى أسفل الصدر والمرفقان قريبان من الجسم، ثم ادفع حتى القفل.`]}},{id:`triceps-pushdown`,group:`arms`,name:{en:`Triceps Pushdown`,ar:`الضغط للأسفل للترايسبس`},equipment:{en:`Cable with bar or rope`,ar:`كابل ببار أو حبل`},level:`beginner`,steps:{en:[`Stand facing a high pulley with elbows bent at 90 degrees and pinned to your sides.`,`Push the attachment down until the arms are straight, then let it rise slowly to the start.`],ar:[`قف مواجهًا بكرًا عاليًا والمرفقان مثنيان 90 درجة ومثبتان بجانب الجسم.`,`ادفع المقبض للأسفل حتى استقامة الذراعين، ثم اتركه يصعد ببطء للبداية.`]}},{id:`overhead-triceps-extension`,group:`arms`,name:{en:`Overhead Triceps Extension`,ar:`مد الترايسبس فوق الرأس`},equipment:{en:`Dumbbell or cable rope`,ar:`دمبل أو حبل كابل`},level:`beginner`,steps:{en:[`Hold the weight overhead with both hands and elbows close to your ears.`,`Bend the elbows to lower the weight behind your head, then extend back to the top.`],ar:[`امسك الوزن فوق رأسك بكلتا اليدين والمرفقان قريبان من الأذنين.`,`اثنِ المرفقين لأنزل الوزن خلف رأسك، ثم امتد للعودة للأعلى.`]}},{id:`skull-crusher`,group:`arms`,name:{en:`Skull Crusher`,ar:`سكال كراشر (مد مستلقٍ)`},equipment:{en:`EZ bar or dumbbells + bench`,ar:`بار زجزاج أو دمبل + بنش`},level:`intermediate`,steps:{en:[`Lie on a bench holding the bar straight above your chest.`,`Bend only the elbows to lower the bar toward your forehead, then extend back up.`],ar:[`استلقِ على بنش ماسكًا البار مستقيمًا فوق صدرك.`,`اثنِ المرفقين فقط لأنزل البار نحو جبهتك، ثم امتد لأعلى.`]}},{id:`bench-dip`,group:`arms`,name:{en:`Bench Dip`,ar:`غطس البنش`},equipment:{en:`Bench or chair`,ar:`بنش أو كرسي`},level:`beginner`,steps:{en:[`Sit on the edge of a bench, place your palms beside your hips, and slide forward off the bench.`,`Bend the elbows to lower until they reach about 90 degrees, then press back up.`],ar:[`اجلس على حافة البنش ويداك بجانب وركيك، ثم انزلق للأمام عن البنش.`,`اثنِ المرفقين للنزول حتى 90 درجة تقريبًا، ثم ادفع لأعلى.`]}},{id:`wrist-curl`,group:`arms`,name:{en:`Wrist Curl`,ar:`مرجفة الرسغ`},equipment:{en:`Dumbbells or barbell`,ar:`دمبل أو بار`},level:`beginner`,steps:{en:[`Rest your forearms on a bench or thighs with wrists hanging over the edge, palms up.`,`Curl the weight up using only the wrists, then lower it into a deep stretch.`],ar:[`استند ساعداك على بنش أو فخذيك والرسغان خارج الحافة والكفان للأعلى.`,`ارفع الوزن بحركة الرسغين فقط، ثم أنزله في شد عميق.`]}}],i=[{id:`barbell-back-squat`,group:`legs`,name:{en:`Barbell Back Squat`,ar:`السكوات بالبار خلف الرقبة`},equipment:{en:`Barbell + rack`,ar:`بار + رف`},level:`advanced`,steps:{en:[`Rest the bar on your upper traps, set the feet shoulder-width, and brace your core.`,`Sit down and back until the hips pass the knees, keeping the chest up and knees tracking over the toes.`,`Drive through the whole foot to stand back up to a full lockout.`],ar:[`ضع البار على أعلى الكتفين، فُت القدمين بعرض الكتفين، وشدّ بطنك.`,`اجلس للأسفل والخلف حتى يتجاوز الحوض الركبتين مع صدر مرفوع وركبتين باتجاه أصابع القدم.`,`ادفع بباطن القدم كاملًا لتقف حتى القفل الكامل.`]}},{id:`front-squat`,group:`legs`,name:{en:`Front Squat`,ar:`سكوات الفرونت`},equipment:{en:`Barbell + rack`,ar:`بار + رف`},level:`advanced`,steps:{en:[`Rack the bar on the front of your shoulders with elbows high and fingertips under the bar.`,`Squat down while keeping the torso upright, then drive back up through the mid-foot.`],ar:[`ثبّت البار على مقدمة الكتفين والمرفقان عاليان وأصابعك تحت البار.`,`انزل في السكوات مع إبقاء الجذع منتصبًا، ثم ادفع لأعلى عبر منتصف القدم.`]}},{id:`leg-press`,group:`legs`,name:{en:`Leg Press`,ar:`ضغط الأرجل`},equipment:{en:`Leg press machine`,ar:`جهاز ضغط الأرجل`},level:`beginner`,steps:{en:[`Sit in the machine with feet on the platform at shoulder width and knees bent to 90 degrees.`,`Press the platform away without locking the knees, then lower slowly until they bend deeply again.`],ar:[`اجلس في الجهاز وقدميك على المنصة بعرض الكتفين والركبتان مثنيتان 90 درجة.`,`ادفع المنصة دون قفل الركبتين، ثم أنزل ببطء حتى ينحني الرُكبتان بعمق مجددًا.`]}},{id:`hack-squat`,group:`legs`,name:{en:`Hack Squat`,ar:`الهاك سكوات`},equipment:{en:`Hack squat machine`,ar:`جهاز هاك سكوات`},level:`intermediate`,steps:{en:[`Place your shoulders under the pads with feet shoulder-width on the platform.`,`Lower until the knees bend past 90 degrees, then press back up with control.`],ar:[`ضع كتفيك تحت الممسدات وقدميك بعرض الكتفين على المنصة.`,`انزل حتى تتجاوز الركبتان 90 درجة، ثم ادفع لأعلى بتحكم.`]}},{id:`leg-extension`,group:`legs`,name:{en:`Leg Extension`,ar:`مد الأرجل`},equipment:{en:`Leg extension machine`,ar:`جهاز مد الأرجل`},level:`beginner`,steps:{en:[`Sit with the pad on the front of your ankles and knees lined up with the machine pivot.`,`Extend the legs until straight, squeeze the thighs for a second, then lower slowly.`],ar:[`اجلس والممسدة على مقدمة كاحليك والركبتان محاذاتان لمحور الجهاز.`,`مد الساقين حتى الاستقامة واضغط الفخذين ثانية، ثم أنزل ببطء.`]}},{id:`lying-leg-curl`,group:`legs`,name:{en:`Lying Leg Curl`,ar:`ثني الأرجل مستلقياً`},equipment:{en:`Leg curl machine`,ar:`جهاز ثني الأرجل`},level:`beginner`,steps:{en:[`Lie face down with the pad on the back of your ankles and hips pressed into the bench.`,`Curl your heels toward your glutes, pause, then lower the weight slowly.`],ar:[`استلقِ على بطنك والممسدة على خلف كاحليك وحوضك مضغوط بالبنش.`,`ارفع كعبيك نحو المؤخرة، توقف، ثم أنزل الوزن ببطء.`]}},{id:`seated-leg-curl`,group:`legs`,name:{en:`Seated Leg Curl`,ar:`ثني الأرجل جالساً`},equipment:{en:`Seated leg curl machine`,ar:`جهاز ثني الأرجل الجالس`},level:`beginner`,steps:{en:[`Sit with the lap pad over your thighs and the ankle pad against the back of your lower legs.`,`Pull your heels down and back under the seat, then return the legs slowly to straight.`],ar:[`اجلس وممسدة الفخذ على ساقيك وممسدة الكاحل على خلف الساقين.`,`اسحب كعبيك للأسفل وللخلف تحت المقعد، ثم أرجع الساقين ببطء للاستقامة.`]}},{id:`romanian-deadlift`,group:`legs`,name:{en:`Romanian Deadlift`,ar:`الرفعة الرومانية`},equipment:{en:`Barbell or dumbbells`,ar:`بار أو دمبل`},level:`intermediate`,steps:{en:[`Stand holding the bar in front of your thighs with a slight bend in the knees.`,`Push the hips back and slide the bar down your legs until you feel a deep hamstring stretch, then stand up.`],ar:[`قف ماسكًا البار أمام فخذيك مع انحناء بسيط في الركبتين.`,`ادفع الحوض للخلف وانزلق بالبار على ساقيك حتى تشعر بشد عميق في خلف الفخذ، ثم انهض.`]}},{id:`walking-lunge`,group:`legs`,name:{en:`Walking Lunge`,ar:`الطعن المتحرك`},equipment:{en:`Dumbbells (optional)`,ar:`دمبل (اختياري)`},level:`beginner`,steps:{en:[`Step forward into a long stride and drop the back knee toward the floor.`,`Push off the front foot to stand and bring the other leg through, repeating down the floor.`],ar:[`اخطُ خطوة أمامية طويلة وأنزل الركبة الخلفية نحو الأرض.`,`ادفع بالقدم الأمامية للوقوف وأحضر الساق الأخرى، وكرر عبر القاعة.`]}},{id:`bulgarian-split-squat`,group:`legs`,name:{en:`Bulgarian Split Squat`,ar:`سكوات بلغاري`},equipment:{en:`Dumbbells + bench`,ar:`دمبل + بنش`},level:`intermediate`,steps:{en:[`Rest the top of one foot on a bench behind you and hold weights at your sides.`,`Lower straight down until the front thigh is parallel to the floor, then push back up.`],ar:[`ضع أعلى قدم واحدة على بنش خلفك وامسك الوزنين على جانبيك.`,`انزل مستقيمًا حتى يوازي الفخذ الأمامي الأرض، ثم ادفع لأعلى.`]}},{id:`goblet-squat`,group:`legs`,name:{en:`Goblet Squat`,ar:`سكوات الجوبلت`},equipment:{en:`Dumbbell or kettlebell`,ar:`دمبل أو كيتل بل`},level:`beginner`,steps:{en:[`Hold one weight against your chest with both hands under it, elbows down.`,`Squat between your feet keeping the chest tall, then drive back up to standing.`],ar:[`امسك وزنًا واحدًا على صدرك باليدين تحته والمرفقان للأسفل.`,`انزل في السكوات بين قدميك مع صدر مرفوع، ثم ادفع للوقوف.`]}},{id:`step-up`,group:`legs`,name:{en:`Step-Up`,ar:`الصعود على المنصة`},equipment:{en:`Box + dumbbells (optional)`,ar:`صندوق + دمبل (اختياري)`},level:`beginner`,steps:{en:[`Stand in front of a knee-height box with one foot on top.`,`Drive through the top leg to stand fully on the box, then lower back down slowly.`],ar:[`قف أمام صندوق بارتفاع الركبة وقدم واحدة فوقه.`,`ادفع بالساق العلوية لتقف كاملًا على الصندوق، ثم انزل ببطء.`]}},{id:`standing-calf-raise`,group:`legs`,name:{en:`Standing Calf Raise`,ar:`رفع السمانة واقفاً`},equipment:{en:`Machine or step`,ar:`جهاز أو درجة`},level:`beginner`,steps:{en:[`Stand with the balls of your feet on the edge of a step or platform.`,`Rise onto your toes as high as possible, pause at the top, then lower into a deep stretch.`],ar:[`قف بأمشاط قدميك على حافة درجة أو منصة.`,`ارتفع على أطراف الأصابع لأقصى ارتفاع، توقف في القمة، ثم انزل في شد عميق.`]}},{id:`seated-calf-raise`,group:`legs`,name:{en:`Seated Calf Raise`,ar:`رفع السمانة جالساً`},equipment:{en:`Seated calf machine`,ar:`جهاز السمانة الجالس`},level:`beginner`,steps:{en:[`Sit with the pad on your knees and the balls of your feet on the platform.`,`Press through the toes to lift the pad, squeeze the calves, then lower slowly.`],ar:[`اجلس والممسدة على ركبتيك وأمشاط قدميك على المنصة.`,`ادفع بأصابع القدم لرفع الممسدة، اضغط السمانة، ثم أنزل ببطء.`]}},{id:`leg-press-calf-raise`,group:`legs`,name:{en:`Leg Press Calf Raise`,ar:`رفع السمانة على جهاز ضغط الأرجل`},equipment:{en:`Leg press machine`,ar:`جهاز ضغط الأرجل`},level:`beginner`,steps:{en:[`Lie in the leg press with only the balls of your feet on the platform.`,`Push the platform up with your toes, pause at the top, then let it come back for a full stretch.`],ar:[`استلقِ في جهاز ضغط الأرجل بأمشاط القدم فقط على المنصة.`,`ادفع المنصة بأطراف أصابعك، توقف في القمة، ثم اتركها ترجع للشد الكامل.`]}},{id:`sumo-squat`,group:`legs`,name:{en:`Sumo Squat`,ar:`سكوات السومو`},equipment:{en:`Dumbbell or kettlebell`,ar:`دمبل أو كيتل بل`},level:`beginner`,steps:{en:[`Stand with feet wide and toes turned out, holding a weight at chest height.`,`Squat straight down between the legs keeping the knees pushed out, then stand back up.`],ar:[`قف بقدمين واسعتين وأصابع للخارج ماسكًا وزنًا بارتفاع الصدر.`,`انزل مستقيمًا بين الساقين مع دفع الركبتين للخارج، ثم انهض.`]}}],a=[{id:`barbell-hip-thrust`,group:`glutes`,name:{en:`Barbell Hip Thrust`,ar:`دفع الحوض بالبار`},equipment:{en:`Barbell + bench`,ar:`بار + بنش`},level:`intermediate`,steps:{en:[`Rest your upper back on a bench with the bar over your hips and knees bent, feet flat.`,`Drive through the heels to lift the hips until your body forms a straight line, squeeze, then lower.`],ar:[`استند بجزء أعلى ظهرك على بنش والبار فوق وركيك والركبتان مثنيتان وقدمان مستويتان.`,`ادفع بالكعبين لرفع الحوض حتى يستقيم جسمك، اضغط، ثم أنزل.`]}},{id:`glute-bridge`,group:`glutes`,name:{en:`Glute Bridge`,ar:`جسر المؤخرة`},equipment:{en:`Bodyweight or dumbbell`,ar:`وزن الجسم أو دمبل`},level:`beginner`,steps:{en:[`Lie on your back with knees bent and feet flat, close to your glutes.`,`Push through the heels to lift the hips into a straight line, squeeze at the top, then lower slowly.`],ar:[`استلقِ على ظهرك والركبتان مثنيتان والقدمان مستويتان قريبًا من المؤخرة.`,`ادفع بالكعبين لرفع الحوض حتى الاستقامة، اضغط في القمة، ثم أنزل ببطء.`]}},{id:`single-leg-glute-bridge`,group:`glutes`,name:{en:`Single-Leg Glute Bridge`,ar:`جسر المؤخرة برجل واحدة`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Lie on your back with one foot flat and the other leg extended straight up or forward.`,`Lift the hips using only the planted leg, keep the hips level, then lower with control.`],ar:[`استلقِ على ظهرك وقدم واحدة مستوية والساق الأخرى ممدودة لأعلى أو أمامك.`,`ارفع الحوض بالساق الثابتة فقط مع إبقاء الحوض مستويًا، ثم أنزل بتحكم.`]}},{id:`cable-kickback`,group:`glutes`,name:{en:`Cable Kickback`,ar:`الرفع الخلفي بالكابل`},equipment:{en:`Cable with ankle strap`,ar:`كابل بحزام كاحل`},level:`beginner`,steps:{en:[`Attach an ankle strap to a low pulley and hold the frame for balance.`,`Kick the working leg straight back and slightly up, squeeze the glute, then return slowly.`],ar:[`ثبّت حزام كاحل على بكر منخفض وامسك الإطار للتوازن.`,`ارفع الساق العاملة مستقيمة للخلف وللأعلى قليلًا، اضغط المؤخرة، ثم ارجع ببطء.`]}},{id:`donkey-kick`,group:`glutes`,name:{en:`Donkey Kick`,ar:`الرفع الخلفي على أربع`},equipment:{en:`Bodyweight or ankle band`,ar:`وزن الجسم أو حزام`},level:`beginner`,steps:{en:[`Start on all fours with hands under the shoulders and knees under the hips.`,`Kick one foot toward the ceiling with the knee bent at 90 degrees, then lower without touching down.`],ar:[`ابدأ على أربع ويداك تحت الكتفين وركبتاك تحت الحوض.`,`ارفع قدمًا واحدة نحو السقف والركبة مثنية 90 درجة، ثم انزل دون لمس الأرض.`]}},{id:`curtsy-lunge`,group:`glutes`,name:{en:`Curtsy Lunge`,ar:`طعن الكورتسي (التقاطع)`},equipment:{en:`Dumbbells (optional)`,ar:`دمبل (اختياري)`},level:`intermediate`,steps:{en:[`Stand tall, then step one leg behind and across your body as if taking a bow.`,`Lower until the front knee bends to 90 degrees, then push back to standing.`],ar:[`قف منتصبًا، ثم اخطُ ساقًا واحدة خلف وعبر جسمك كأنك تعتذر.`,`انزل حتى تنثني الركبة الأمامية 90 درجة، ثم ادفع للوقوف.`]}},{id:`kettlebell-swing`,group:`glutes`,name:{en:`Kettlebell Swing`,ar:`تأرجح الكيتل بل`},equipment:{en:`Kettlebell`,ar:`كيتل بل`},level:`intermediate`,steps:{en:[`Stand over the kettlebell, hinge to grab it, and hike it back between your legs.`,`Snap the hips forward to swing the bell to chest height, then let it fall back into the hinge.`],ar:[`قف فوق الكيتل بل، انحنِ لتمسكه، وارفعه للخلف بين ساقيك.`,`ادفع الحوض للأمام بقوة ليرتفع الوزن بارتفاع الصدر، ثم اتركه يعود للانحناء.`]}},{id:`clamshell`,group:`glutes`,name:{en:`Clamshell`,ar:`تمرين المحارة`},equipment:{en:`Resistance band (optional)`,ar:`حزام مقاومة (اختياري)`},level:`beginner`,steps:{en:[`Lie on your side with knees bent and stacked, feet together.`,`Open the top knee up like a clam while keeping the hips still, then close slowly.`],ar:[`استلقِ على جانبك والركبتان مثنيتان فوق بعضهما والقدمان معًا.`,`افتح الركبة العلوية كالمحارة مع إبقاء الحوض ثابتًا، ثم أغلق ببطء.`]}}],o=[{id:`plank`,group:`core`,name:{en:`Plank`,ar:`البلانك`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Rest on your forearms and toes with the elbows under the shoulders.`,`Keep a straight line from head to heels and squeeze the abs and glutes for time.`],ar:[`اتسك على ساعديك وأطراف أصابعك والمرفقان تحت الكتفين.`,`حافظ على خط مستقيم من الرأس إلى الكعبين واشد البطن والمؤخرة واتصبر بالزمن.`]}},{id:`side-plank`,group:`core`,name:{en:`Side Plank`,ar:`البلانك الجانبي`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Lie on your side and prop yourself up on one forearm with the elbow under the shoulder.`,`Lift the hips so the body forms a straight line, hold, then repeat on the other side.`],ar:[`استلقِ على جانبك واتسك على ساعد واحد والمرفق تحت الكتف.`,`ارفع الحوض حتى يستقيم الجسم، اتصبر، ثم كرر على الجانب الآخر.`]}},{id:`crunch`,group:`core`,name:{en:`Crunch`,ar:`الكرنش`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Lie on your back with knees bent and hands lightly behind your ears.`,`Curl the shoulder blades off the floor by contracting the abs, then lower slowly.`],ar:[`استلقِ على ظهرك والركبتان مثنيتان واليدان خلف الأذنين بخفة.`,`ارفع لوحي الكتف عن الأرض بانكماش البطن، ثم انزل ببطء.`]}},{id:`bicycle-crunch`,group:`core`,name:{en:`Bicycle Crunch`,ar:`الكرنش الدراجة`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Lie on your back with hands behind your ears and legs raised, knees bent.`,`Bring the opposite elbow and knee together while extending the other leg, alternating in a cycling rhythm.`],ar:[`استلقِ على ظهرك واليدان خلف الأذنين والساقان مرفوعتان والركبتان مثنيتان.`,`قرب المرفق المعاكس من الركبة مع مد الساق الأخرى، وتناوب بإيقاع الدراجة.`]}},{id:`hanging-leg-raise`,group:`core`,name:{en:`Hanging Leg Raise`,ar:`رفع الأرجل متدلياً`},equipment:{en:`Pull-up bar`,ar:`بار العقلة`},level:`advanced`,steps:{en:[`Hang from a bar with straight arms and shoulders engaged.`,`Raise the legs to hip height or higher without swinging, then lower them slowly.`],ar:[`تدلَّ من البار بذراعين ممدودتين وكتفين مشدودين.`,`ارفع الساقين حتى مستوى الحوض أو أعلى دون تأرجح، ثم أنزلهما ببطء.`]}},{id:`lying-leg-raise`,group:`core`,name:{en:`Lying Leg Raise`,ar:`رفع الأرجل مستلقياً`},equipment:{en:`Bodyweight or bench`,ar:`وزن الجسم أو بنش`},level:`beginner`,steps:{en:[`Lie flat with hands under your glutes and legs straight.`,`Raise the legs to vertical, then lower them slowly without letting the lower back arch.`],ar:[`استلقِ مستويًا واليدان تحت المؤخرة والساقان ممدودتان.`,`ارفع الساقين حتى العمود، ثم أنزلهما ببطء دون تقويس أسفل الظهر.`]}},{id:`russian-twist`,group:`core`,name:{en:`Russian Twist`,ar:`التواء الروسي`},equipment:{en:`Plate or dumbbell (optional)`,ar:`قرص أو دمبل (اختياري)`},level:`beginner`,steps:{en:[`Sit with knees bent, heels on the floor, and hold the weight at chest height.`,`Lean back slightly and rotate the weight from side to side, touching the floor beside each hip.`],ar:[`اجلس والركبتان مثنيتان والكعبان على الأرض والوزن بارتفاع الصدر.`,`مِل للخلف قليلًا ودرّ الوزن من جانب لآخر ملامسًا الأرض بجانب كل ورك.`]}},{id:`mountain-climber`,group:`core`,name:{en:`Mountain Climber`,ar:`متسلق الجبال`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Start in a high plank with hands under the shoulders and body rigid.`,`Drive one knee toward the chest, then switch legs quickly as if sprinting in place.`],ar:[`ابدأ في بلانك مرتفع واليدان تحت الكتفين والجسم متصلب.`,`ادفع ركبة نحو الصدر ثم بدّل بسرعة كأنك تجري في مكانك.`]}},{id:`dead-bug`,group:`core`,name:{en:`Dead Bug`,ar:`تمرين الحشرة الميتة`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Lie on your back with arms straight up and knees bent at 90 degrees over the hips.`,`Lower the opposite arm and leg toward the floor while keeping the lower back pressed down, then switch.`],ar:[`استلقِ على ظهرك والذراعان للأعلى والركبتان مثنيتان 90 درجة فوق الحوض.`,`أنزل الذراع والساق المتعاكسين نحو الأرض مع ضغط أسفل الظهر، ثم بدّل.`]}},{id:`bird-dog`,group:`core`,name:{en:`Bird Dog`,ar:`تمرين الكلب المستمع`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Start on all fours with a flat back and braced core.`,`Extend the opposite arm and leg until level with the torso, pause, then return and switch sides.`],ar:[`ابدأ على أربع بظهر مستوٍ وبطن مشدود.`,`امتد بالذراع والساق المتعاكسين حتى مستوى الجذع، توقف، ثم ارجع وبدّل الجانب.`]}},{id:`ab-wheel-rollout`,group:`core`,name:{en:`Ab Wheel Rollout`,ar:`معدة الأب ويل`},equipment:{en:`Ab wheel`,ar:`عجلة البطن`},level:`advanced`,steps:{en:[`Kneel with hands on the ab wheel directly under the shoulders.`,`Roll forward as far as you can keep the back flat, then pull the wheel back with the abs.`],ar:[`اركع ويداك على عجلة البطن تحت الكتفين مباشرة.`,`تدحرج للأمام لأبعد مدى يبقى فيه ظهرك مستوياً، ثم اسحب العجلة للخلف بالبطن.`]}},{id:`cable-crunch`,group:`core`,name:{en:`Cable Crunch`,ar:`كرنش الكابل`},equipment:{en:`Cable + rope`,ar:`كابل + حبل`},level:`intermediate`,steps:{en:[`Kneel below a high pulley holding the rope beside your head.`,`Crunch down by curling the ribs toward the pelvis, then rise slowly keeping tension.`],ar:[`اركع تحت بكر عالٍ ماسكًا الحبل بجانب رأسك.`,`انحنِ بضم الضلوع نحو الحوض، ثم ارجع ببطء مع الحفاظ على الشد.`]}},{id:`flutter-kicks`,group:`core`,name:{en:`Flutter Kicks`,ar:`رفرفة الأرجل`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Lie on your back with legs straight and lifted slightly off the floor, hands at your sides.`,`Alternate small up-and-down kicks from the hips while keeping the lower back pressed down.`],ar:[`استلقِ على ظهرك والساقان ممدودتان مرفوعتان قليلًا واليدان على الجانبين.`,`ناوب ضربات صغيرة من الحوض للأعلى والأسفل مع ضغط أسفل الظهر على الأرض.`]}},{id:`v-up`,group:`core`,name:{en:`V-Up`,ar:`الفي أب`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`intermediate`,steps:{en:[`Lie flat with arms extended overhead and legs straight.`,`Lift the legs and torso together to touch the toes at the top, forming a V, then lower with control.`],ar:[`استلقِ مستويًا والذراعان ممدودتان فوق الرأس والساقان ممدودتان.`,`ارفع الساقين والجذع معًا لملامسة أصابع القدم في شكل حرف V، ثم انزل بتحكم.`]}}],s=[{id:`incline-treadmill-walk`,group:`cardio`,name:{en:`Incline Treadmill Walk`,ar:`المشي المائل على السير`},equipment:{en:`Treadmill`,ar:`جهاز السير`},level:`beginner`,steps:{en:[`Set the treadmill to a brisk walking speed with an 8-12 percent incline.`,`Walk without holding the handrails, keeping an upright posture and steady breathing for 20-40 minutes.`],ar:[`اضبط السير على سرعة مشي سريعة بميل 8-12 بالمئة.`,`امشِ دون الإمساك بالمقابض بجسم منتصب وتنفس منتظم لمدة 20-40 دقيقة.`]}},{id:`stationary-bike`,group:`cardio`,name:{en:`Stationary Bike`,ar:`الدراجة الثابتة`},equipment:{en:`Exercise bike`,ar:`دراجة الجيم`},level:`beginner`,steps:{en:[`Adjust the seat so the knee stays slightly bent at the bottom of each pedal stroke.`,`Pedal at a steady pace or alternate 1-minute hard efforts with 2-minute easy spins.`],ar:[`اضبط المقعد لتبقى الركبة مثنية قليلًا في أسفل كل دورة دواسة.`,`اتفق بإيقاع ثابت أو تناوب دقيقة قوية مع دقيقتين هادئتين.`]}},{id:`rowing-machine`,group:`cardio`,name:{en:`Rowing Machine`,ar:`جهاز التجديف`},equipment:{en:`Rower`,ar:`جهاز التجديف`},level:`intermediate`,steps:{en:[`Start with legs bent, arms straight, and torso leaning slightly forward.`,`Drive with the legs, then lean back and pull the handle to the ribs, then reverse the order on the return.`],ar:[`ابدأ والركبتان مثنيتان والذراعان ممدودتان والجذع مائل قليلًا للأمام.`,`ادفع بالساقين، ثم مِل للخلف واسحب المقبض إلى ضلوعك، ثم اعكس الترتيب عند العودة.`]}},{id:`elliptical`,group:`cardio`,name:{en:`Elliptical`,ar:`جهاز الإليبتيكال`},equipment:{en:`Elliptical machine`,ar:`جهاز إليبتيكال`},level:`beginner`,steps:{en:[`Step onto the pedals and grip the moving handles lightly.`,`Glide in a smooth oval motion, pushing and pulling the handles, for 20-40 minutes.`],ar:[`اصعد على الدواسات وامسك المقابض المتحركة بخفة.`,`انزلق بحركة بيضاوية سلسة دافعًا وساحبًا المقابض لمدة 20-40 دقيقة.`]}},{id:`stair-climber`,group:`cardio`,name:{en:`Stair Climber`,ar:`جهاز صعود الدرج`},equipment:{en:`Stair machine`,ar:`جهاز الدرج`},level:`beginner`,steps:{en:[`Step onto the machine and let the steps rise at a moderate pace.`,`Climb with full steps, resting hands lightly on the rails only for balance.`],ar:[`اصعد على الجهاز واترك الدرج يرتفع بوتيرة معتدلة.`,`اصعد بخطوات كاملة مع وضع اليدين بخفة على المقابض للتوازن فقط.`]}},{id:`jump-rope`,group:`cardio`,name:{en:`Jump Rope`,ar:`نط الحبل`},equipment:{en:`Jump rope`,ar:`حبل النط`},level:`beginner`,steps:{en:[`Hold the handles with elbows near your ribs and turn the rope with the wrists.`,`Jump just high enough for the rope to pass under the feet, landing softly on the balls of the feet.`],ar:[`امسك المقبضين والمرفقان قريبان من الجسم وأدر الحبل بالرسغين.`,`اقفز بقدر يسمح للحبل بالمرور تحت قدميك، وهوط على مشاش القدم بهدوء.`]}},{id:`burpee`,group:`cardio`,name:{en:`Burpee`,ar:`البيربي`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`intermediate`,steps:{en:[`From standing, squat down, place your hands on the floor, and jump the feet back to a plank.`,`Perform a push-up, jump the feet back in, and explode up into a jump with arms overhead.`],ar:[`من الوقوف، انزل في سكوات، ضع يديك على الأرض، وقفز بقدميك للخلف إلى بلانك.`,`اعمل ضغطة، ثم اقفز بالقدمين للأمام، وانفجر نحو الأعلى بقفزة والذراعان فوق الرأس.`]}},{id:`jumping-jack`,group:`cardio`,name:{en:`Jumping Jack`,ar:`الجامبى جاك (فتحة النط)`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Stand with feet together and arms at your sides.`,`Jump the feet wide while raising the arms overhead, then jump back to the start, keeping a steady rhythm.`],ar:[`قف والقدمان معًا والذراعان على الجانبين.`,`اقفز بفتح القدمين مع رفع الذراعين فوق الرأس، ثم اقفز للعودة بإيقاع ثابت.`]}},{id:`high-knees`,group:`cardio`,name:{en:`High Knees`,ar:`الجري بركب عالية`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Run in place, driving each knee up to hip height.`,`Stay on the balls of the feet and pump the arms in rhythm with the legs.`],ar:[`اجرِ في مكانك وارفع كل ركبة حتى مستوى الحوض.`,`ابقَ على مشاش القدمين وضخ الذراعين بإيقاع الساقين.`]}},{id:`sled-push`,group:`cardio`,name:{en:`Sled Push`,ar:`دفع الزحليقة`},equipment:{en:`Sled + turf or track`,ar:`زحليقة + مسار`},level:`advanced`,steps:{en:[`Grip the sled handles low, lean into the sled at about 45 degrees.`,`Drive with short, powerful steps, keeping the arms locked out, for a set distance then rest.`],ar:[`امسك مقابض الزحليقة منخفضة ومِل نحوها بزاوية 45 درجة.`,`ادفع بخطوات قصيرة قوية مع ذراعين ممدودتين لمسافة محددة ثم استرح.`]}}],c=[{id:`thruster`,group:`fullbody`,name:{en:`Thruster (Squat to Press)`,ar:`الثرستر (سكوات وضغط)`},equipment:{en:`Barbell or dumbbells`,ar:`بار أو دمبل`},level:`advanced`,steps:{en:[`Hold the weight at shoulder height and squat down with a braced core.`,`Drive out of the squat and use that momentum to press the weight overhead, then repeat in one fluid motion.`],ar:[`امسك الوزن بارتفاع الكتف وانزل في سكوات مع بطن مشدود.`,`انهض من السكوات واستخدم الزخم للضغط فوق الرأس، وكرر بحركة واحدة سلسة.`]}},{id:`dumbbell-snatch`,group:`fullbody`,name:{en:`Dumbbell Snatch`,ar:`سناتش الدمبل`},equipment:{en:`Dumbbell`,ar:`دمبل`},level:`intermediate`,steps:{en:[`Stand over the dumbbell, hinge with a flat back, and grip it with one hand.`,`Explode through the hips and pull the weight straight overhead in one motion, then lower and switch arms.`],ar:[`قف فوق الدمبل، انحنِ بظهر مستوٍ، وامسكه بيد واحدة.`,`انفجر من الحوض واسحب الوزن مستقيمًا فوق رأسك بحركة واحدة، ثم أنزل وبدّل الذراع.`]}},{id:`turkish-get-up`,group:`fullbody`,name:{en:`Turkish Get-Up`,ar:`النهضة التركية`},equipment:{en:`Kettlebell or dumbbell`,ar:`كيتل بل أو دمبل`},level:`advanced`,steps:{en:[`Lie on your back pressing one weight overhead with the knee on that side bent.`,`Move through deliberate steps — elbow, hand, hips — to stand up while keeping the weight overhead, then reverse back down.`],ar:[`استلقِ على ظهرك مرفوعًا وزنًا فوق رأسك والركبة على تلك الجهة مثنية.`,`انتقل بخطوات متأنية — مرفق، يد، حوض — حتى تقف مع إبقاء الوزن للأعلى، ثم اعكس الطريق.`]}},{id:`farmers-walk`,group:`fullbody`,name:{en:`Farmer's Walk`,ar:`مشية الفلاح`},equipment:{en:`Heavy dumbbells`,ar:`دمبل ثقيل`},level:`beginner`,steps:{en:[`Pick up a heavy weight in each hand with tall posture and shoulders back.`,`Walk with short, quick steps while keeping a tight grip and level shoulders, then set the weights down carefully.`],ar:[`ارفع وزنًا ثقيلًا في كل يد بجسم منتصب وكتفين للخلف.`,`امشِ بخطوات قصيرة سريعة مع قبضة قوية وكتفين مستويين، ثم ضع الوزنين بحذر.`]}},{id:`bear-crawl`,group:`fullbody`,name:{en:`Bear Crawl`,ar:`الزحف على أربع`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`beginner`,steps:{en:[`Start on all fours with the knees hovering an inch off the floor.`,`Crawl forward by moving the opposite hand and foot together, keeping the hips low and level.`],ar:[`ابدأ على أربع والركبتان معلقتان بضع سنتيمترات عن الأرض.`,`ازحف للأمام بتحريك اليد والقدم المتعاكسين معًا مع إبقاء الحوض منخفضًا ومستويًا.`]}},{id:`battle-ropes`,group:`fullbody`,name:{en:`Battle Ropes`,ar:`حبال القتال`},equipment:{en:`Battle ropes`,ar:`حبال قتال`},level:`beginner`,steps:{en:[`Hold one rope end in each hand in a half-squat stance.`,`Slam alternating waves as fast as possible for 20-40 seconds, keeping the core braced.`],ar:[`امسك طرف حبل في كل يد بوضع نصف سكوات.`,`اضرب أمواجًا متبادلة بأسرع ما يمكن لمدة 20-40 ثانية مع بطن مشدود.`]}},{id:`wall-ball`,group:`fullbody`,name:{en:`Wall Ball`,ar:`رمية الكرة على الحائط`},equipment:{en:`Medicine ball + wall target`,ar:`كرة طبية + هدف على حائط`},level:`intermediate`,steps:{en:[`Stand about an arm’s length from a wall holding a medicine ball at chest height.`,`Squat, then drive up and throw the ball at a target high on the wall, catch it, and drop straight into the next squat.`],ar:[`قف على بُعد ذراع من الحائط ماسكًا كرة طبية بارتفاع الصدر.`,`انزل في سكوات، ثم ادفع وارمِ الكرة نحو هدف عالٍ على الحائط، والتقطها وانزل للسكوات التالي.`]}},{id:`renegade-row`,group:`fullbody`,name:{en:`Renegade Row`,ar:`الصف المجنّد`},equipment:{en:`Hex dumbbells`,ar:`دمبل سداسي`},level:`advanced`,steps:{en:[`Start in a high plank holding a dumbbell in each hand, feet wide for stability.`,`Row one dumbbell to your hip while bracing against rotation, then alternate sides.`],ar:[`ابدأ في بلانك مرتفع بدمبل في كل يدة وقدمين متباعدتين للاستقرار.`,`اسحب دمبلًا نحو الورك مع مقاومة الدوران، ثم بدّل الجانب.`]}},{id:`squat-jump`,group:`fullbody`,name:{en:`Squat Jump`,ar:`قفزة السكوات`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`intermediate`,steps:{en:[`Squat down until the thighs are near parallel to the floor.`,`Explode up into a maximum vertical jump, land softly back into the squat, and repeat.`],ar:[`انزل في سكوات حتى يقترب الفخذان من الأفقي.`,`انفجر لأعلى في قفزة رأسية قصوى، وهوط بنعومة في السكوات، وكرر.`]}},{id:`jumping-lunge`,group:`fullbody`,name:{en:`Jumping Lunge`,ar:`الطعن بالقفز`},equipment:{en:`Bodyweight`,ar:`وزن الجسم`},level:`advanced`,steps:{en:[`Drop into a lunge with both knees bent to about 90 degrees.`,`Jump up explosively and switch legs mid-air, landing softly in a lunge with the other leg forward.`],ar:[`انزل في طعنة والركبتان مثنيتان 90 درجة تقريبًا.`,`اقفز بقوة وبدّل الساقين في الهواء، وهوط بنعومة في طعنة بالساق الأخرى.`]}}],l=[...e,...t,...n,...r,...i,...a,...o,...s,...c],u=[`chest`,`back`,`shoulders`,`arms`,`legs`,`glutes`,`core`,`cardio`,`fullbody`];export{u as n,l as t};